export const PRIMARY_PAGE_ROUTE_NAMES = [
  'HomeScreen',
  'ConsultScreen',
  'ConciergeScreen',
  'ProfileScreen',
] as const;

export const isPrimaryPageRoute = (routeName?: string): boolean =>
  PRIMARY_PAGE_ROUTE_NAMES.some(
    (primaryRouteName: string): boolean => primaryRouteName === routeName,
  );

export const getPrimaryPageStatusBarStyle = (
  uiTheme?: UITheme | null,
): {
  backgroundColor: string;
  barStyle: 'light-content' | 'dark-content';
} => {
  const isDark = uiTheme?.dark === true;
  const darkBackground = uiTheme?.colors?.$background;

  return {
    backgroundColor:
      isDark && darkBackground
        ? darkBackground
        : APP_PAGE_HEADER_BACKGROUND_COLOR,
    barStyle: isDark ? 'light-content' : 'dark-content',
  };
};

export const usePrimaryPageStatusBar = (): void => {
  const { uiTheme, changeStatusBarTextColor, changeStatusBarBackgroundColor } =
    useThemeProvider();
  const statusBarStyle = getPrimaryPageStatusBarStyle(uiTheme);

  useFocusEffect(
    useCallback((): void => {
      changeStatusBarTextColor?.(statusBarStyle.barStyle);
      changeStatusBarBackgroundColor?.(statusBarStyle.backgroundColor);
    }, [
      changeStatusBarBackgroundColor,
      changeStatusBarTextColor,
      statusBarStyle.backgroundColor,
      statusBarStyle.barStyle,
    ]),
  );
};

