const keyboardHideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
const adjustTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
const adjustRequestRef = useRef(0);
const [sheetKeyboardHeight, setSheetKeyboardHeight] = useState(0);
const [contentShift, setContentShift] = useState(0);

const readKeyboardTop = useCallback((event?: { endCoordinates?: { height?: number; screenY?: number } }) => {
  const metrics = event?.endCoordinates ?? Keyboard.metrics();
  const height = metrics?.height ?? 0;
  const screenY = metrics?.screenY ?? 0;
  const windowHeight = Dimensions.get("window").height;
  if (screenY > 0 && screenY < windowHeight - 20) {
    return screenY;
  }
  if (height > 0) {
    return windowHeight - height;
  }
  return 0;
}, []);

const adjustSheetContentForKeyboard = useCallback(() => {
  if (Platform.OS !== "android") {
    return;
  }
  const keyboardTop = keyboardTopRef.current;
  if (keyboardTop <= 0) {
    return;
  }
  const input = TextInput.State.currentlyFocusedInput() as SheetTextInputHandle | null;
  if (input == null || typeof input.measureInWindow !== "function") {
    return;
  }
  const requestId = adjustRequestRef.current + 1;
  adjustRequestRef.current = requestId;
  input.measureInWindow((_x, y, _width, height) => {
    if (requestId !== adjustRequestRef.current) {
      return;
    }
    const overlap = y + height + PERSONAL_INFO_FIELD_GAP - keyboardTop;
    if (overlap <= 8) {
      return;
    }
    const windowHeight = Dimensions.get("window").height;
    const maxShift = Math.max(0, windowHeight - keyboardTop);
    const next = Math.min(contentShiftRef.current + overlap, maxShift);
    contentShiftRef.current = next;
    setContentShift(next);
  });
}, []);

