export const handleMyAppointmentHardwareBack = (): boolean => {
  leaveMyAppointment();
  return true;
};

export const PERSONAL_INFO_FIELD_GAP = 24;

export type KeyboardFrame = {
  height?: number;
  screenY?: number;
};

export const keyboardTopFromFrame = (
  frame: KeyboardFrame | null | undefined,
  windowHeight: number,
): number => {
  const height = frame?.height ?? 0;
  const screenY = frame?.screenY ?? 0;
  if (screenY > 0 && screenY < windowHeight - 20) {
    return screenY;
  }
  if (height > 0) {
    return Math.max(0, windowHeight - height);
  }
  return 0;
};

// Absolute shift from the field's unshifted position, so a second keyboard
// frame on either platform does not stack on top of the current translation.
export const nextPersonalInfoContentShift = ({
  fieldY,
  fieldHeight,
  keyboardTop,
  currentShift,
  windowHeight,
  gap = PERSONAL_INFO_FIELD_GAP,
}: {
  fieldY: number;
  fieldHeight: number;
  keyboardTop: number;
  currentShift: number;
  windowHeight: number;
  gap?: number;
}): number => {
  if (keyboardTop <= 0) {
    return 0;
  }
  const unshiftedBottom = fieldY + fieldHeight + currentShift;
  const needed = unshiftedBottom + gap - keyboardTop;
  if (needed <= 8) {
    return 0;
  }
  const maxShift = Math.max(0, windowHeight - keyboardTop);
  return Math.min(needed, maxShift);
};

