import {
  keyboardTopFromFrame,
  nextPersonalInfoContentShift,
} from '../src/screens/my-appointment-screen/my-appointment-screen.utils';

describe('personal info sheet keyboard shift', () => {
  test('uses the keyboard top from screenY on iOS and Android', () => {
    expect(keyboardTopFromFrame({height: 336, screenY: 508}, 844)).toBe(508);
  });

  test('falls back to keyboard height when screenY is missing', () => {
    expect(keyboardTopFromFrame({height: 320, screenY: 0}, 800)).toBe(480);
    expect(keyboardTopFromFrame({height: 320}, 800)).toBe(480);
  });

  test('lifts a covered field above the keyboard without stacking a second frame', () => {
    const windowHeight = 844;
    const keyboardTop = 508;
    const first = nextPersonalInfoContentShift({
      fieldY: 620,
      fieldHeight: 48,
      keyboardTop,
      currentShift: 0,
      windowHeight,
    });
    expect(first).toBe(184);

    const paintedFieldY = 620 - first;
    const second = nextPersonalInfoContentShift({
      fieldY: paintedFieldY,
      fieldHeight: 48,
      keyboardTop,
      currentShift: first,
      windowHeight,
    });
    expect(second).toBe(first);
  });

  test('clears the shift when the focused field is already above the keyboard', () => {
    expect(nextPersonalInfoContentShift({
      fieldY: 200,
      fieldHeight: 48,
      keyboardTop: 508,
      currentShift: 184,
      windowHeight: 844,
    })).toBe(0);
  });

  test('returns the content to its original position after the keyboard hides', () => {
    expect(nextPersonalInfoContentShift({
      fieldY: 436,
      fieldHeight: 48,
      keyboardTop: 0,
      currentShift: 184,
      windowHeight: 844,
    })).toBe(0);
  });
});

