const ts = require('typescript');
const path = require('path');
const { execSync } = require('child_process');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, root);
const changed = [
  'src/components/questionnaire-widget/questionnaire-widget.tsx',
  'src/screens/consult-screen/consult-screen.tsx',
  'src/screens/home/home-screen/home-screen.styles.ts',
  'src/screens/home/home-screen/home-screen.tsx',
  'src/screens/plan-list-screen/plan-list-screen.tsx',
].map((p) => path.join(root, p));

function rel(file) {
  return path.relative(root, file);
}

function createProgram(fileOverrides) {
  const host = ts.createCompilerHost(parsed.options, true);
  const originalRead = host.readFile.bind(host);
  host.readFile = (fileName) => {
    const abs = path.isAbsolute(fileName) ? fileName : path.join(root, fileName);
    if (fileOverrides.has(abs)) return fileOverrides.get(abs);
    return originalRead(fileName);
  };
  return ts.createProgram({
    rootNames: parsed.fileNames,
    options: parsed.options,
    host,
  });
}

function collect(program, label) {
  const sfSet = new Set(changed.map((f) => path.normalize(f)));
  const diags = [];
  for (const file of changed) {
    const sf = program.getSourceFile(file);
    if (!sf) {
      diags.push({ file: rel(file), category: 'missing', code: 0, message: 'source file not in program' });
      continue;
    }
    const all = [
      ...program.getSemanticDiagnostics(sf),
      ...program.getSyntacticDiagnostics(sf),
      ...program.getSuggestionDiagnostics(sf),
    ];
    for (const d of all) {
      const filePath = d.file ? rel(d.file.fileName) : '';
      if (d.file && !sfSet.has(path.normalize(d.file.fileName))) continue;
      const pos = d.file && typeof d.start === 'number'
        ? d.file.getLineAndCharacterOfPosition(d.start)
        : null;
      diags.push({
        label,
        file: filePath,
        line: pos ? pos.line + 1 : 0,
        col: pos ? pos.character + 1 : 0,
        category: ts.DiagnosticCategory[d.category],
        code: d.code,
        message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
      });
    }
  }
  return diags;
}

const baseOverrides = new Map();
for (const file of changed) {
  const relPath = rel(file);
  const content = execSync(`git show origin/1.2.3:${relPath}`, { encoding: 'utf8', maxBuffer: 20 * 1024 * 1024 });
  baseOverrides.set(path.normalize(file), content);
}

const headProgram = createProgram(new Map());
const baseProgram = createProgram(baseOverrides);
const headDiags = collect(headProgram, 'head');
const baseDiags = collect(baseProgram, 'base');

function key(d) {
  return [d.file, d.line, d.col, d.code, d.message].join('|');
}
const baseKeys = new Set(baseDiags.map(key));
const headKeys = new Set(headDiags.map(key));
const added = headDiags.filter((d) => !baseKeys.has(key(d)));
const removed = baseDiags.filter((d) => !headKeys.has(key(d)));

console.log(JSON.stringify({
  headCount: headDiags.length,
  baseCount: baseDiags.length,
  added,
  removed,
  headSuggestion: headDiags.filter((d) => d.category === 'Suggestion' || d.code === 6385 || d.code === 6387 || d.code === 6380),
}, null, 2));
EOF

content.text:
# Code Review: PR 585

## 摘要

- 范围：Bitbucket PR 585，`1.2.3-ivan-dev` 合入 `1.2.3`
- 端点：`a116c9aab711b87d842f08f6f9b20473e0d8171e` -> `ce29846b416a20f1361815ab349a23d906315f55`
- Changed files：7（`.env`、`.env.development`、问卷组件、咨询页、首页样式、首页、计划列表）
- 目标分支保留审计：target tip 即 merge `ce29846b` 的目标侧父提交 `a116c9aa`；范围内 1 个 merge。已核对 parent-to-merge diff，`1.2.3` 上的 bridgeless `LayoutAnimation` 保护仍在最终文件中。完成。
- 结论：1 个 Critical

## Critical

### [Critical] 完成后改答案，计划列表仍显示上一次推荐

本次修改位置：

- `src/components/questionnaire-widget/questionnaire-widget.tsx:147-151`
- `src/components/questionnaire-widget/questionnaire-widget.tsx:204-207`
- `src/components/questionnaire-widget/questionnaire-widget.tsx:307`
- `src/components/questionnaire-widget/questionnaire-widget.tsx:139-144`（相对 `1.2.3` 删除，commit `7058d3fc`；删除 `isComplete && isQuestionnaireOpen` 时自动收起问卷的 `useEffect`）

受影响历史代码：

- `src/screens/plan-list-screen/plan-list-screen.tsx:384-394`：`setPlanList(sortedList)` 仍然只保留上一次 `productIds` 命中的计划
- `src/screens/plan-list-screen/plan-list-screen.tsx:193`：`recommendedIds.includes(card.id)` 对旧推荐 id 仍为 true
- `src/screens/plan-list-screen/plan-list-screen.tsx:204`：旧卡片继续使用 `recommendedItemPlan`
- `src/screens/plan-list-screen/plan-list-screen.tsx:262-263`：选中这些旧卡片后，`productId: selectedPlan.id` 仍会进入购买页

问题：

问卷到达 `PRODUCT` 结果后，推荐列表已经生效，问卷不再自动收起，最后一题仍可操作。此时改选另一项，或按上一题返回，组件只把 `isComplete` 设为 false，没有清掉父级的 `recommendedIds`、`planList` 和 `selectedPlan`。用户看到的选项已经变了，列表仍是上一套可购买计划，并能直接购买。

证据：

`1.2.3` 在 `isComplete` 时不渲染题目（原 `questionnaire-widget.tsx:298`），并用 `useEffect` 收起问卷，完成后不能改选或返回。这次删掉这两处后，`handleSelectItem` 和 `handleTogglePrev` 只改本地完成态。父级清推荐的逻辑只挂在 `onClose`（`plan-list-screen.tsx:410-417`），改答案和返回都不会走到它。`onProductRecommended` 也只在下一次 `PRODUCT` 完成时覆盖列表。

修改建议：

离开已完成结果时复用现有的清推荐逻辑。没有上一题时，上一题按钮不要改完成态。

```tsx
const clearRecommendation = (): void => {
  setRecommendedIds([]);
  setIsFromRecommendation(false);
  setPlanList(originalPlanList);
  setSelectedId(0);
  setPlanType('All');
  setSelectedPlan(null);
};

const handleSelectItem = (index: number): void => {
  if (isComplete && index !== selectedIndex) {
    setIsComplete(false);
    onAnswersChanged?.();
  }
  setSelectedIndex(index);
};

const handleTogglePrev = (): void => {
  if (!previousIds.length) return;

  if (isComplete) {
    setIsComplete(false);
    onAnswersChanged?.();
  }

  const prevId = previousIds[previousIds.length - 1];
  setSelectedIndex(prevId.qAId);
  setPreviousIds(previousIds.slice(0, -1));
  // existing question lookup unchanged
};
```

计划列表把 `onClose` 和 `onAnswersChanged` 都接到 `clearRecommendation`。

手动自测：

前置条件：计划列表已加载；问卷存在一条走到 `PRODUCT` 且 `products` 非空的路径，这些 id 能命中可购买计划。

步骤：

1. 打开计划推荐并答到出现推荐计划，确认下一步按钮禁用。
2. 在当前题改选另一项，先不要按下一步。
3. 再走一遍，答完后改按上一题，回到前一题。

预期结果：修复前，两步之后列表仍是上一套推荐，卡片可点开并购买。修复后，改选或返回都会清空推荐，列表回到全部可购买计划；再次按下一步后才应用新结果。

平台差异（React Native 适用）：

- Android：未验证。失败路径在共享的问卷状态和计划列表状态中。
- iOS：未验证。失败路径与 Android 相同，未做设备确认。

## 验证边界

- 已执行：只读核对 PR 585 的 base/head。本地 `HEAD` 与 PR head 同为 `ce29846b`，工作区干净，未把额外本地改动纳入范围。检查了 merge `ce29846b` 的两个父提交。
- 已执行：项目 TypeScript 5.9.3，按当前 `tsconfig.json` 对 5 个变更 `.ts`/`.tsx` 取 semantic、syntactic 和 `getSuggestionDiagnostics`，并用同一配置替换为 `1.2.3` 文件内容做差分。变更 hunk 没有新增诊断，没有 TS6385/TS6387。
- 已执行：`npx jest __tests__/consult-screen.test.tsx --no-coverage --watchman=false`，1 个失败。断言仍期望 `consult_page_title`，页面现在使用 `consult`。`en`、`zh-Hans`、`zh-Hant` 都有 `consult`，不构成缺翻译。
- 未执行：全量 Jest、ESLint，以及 Android/iOS 真机或模拟器。Bitbucket pipeline 未配置这些检查。

