const CHINA_PLAN_LABELS = new Set([
  'china plan',
  'heals china plan',
  '中国计划',
  '中國計劃',
]);

/** Same id as constants.chinaPlanId. Kept here so plan matching does not import the app barrel. */
export const CHINA_PLAN_ID = '77b08f92-13fd-4363-9f77-8a2b617a0f1b';

const normalizeLabel = (value: unknown): string => {
  if (typeof value !== 'string') {
    return '';
  }

  return value.trim().toLowerCase();
};

/**
 * Consult shows this reminder in both dev and prod. Match the catalog name,
 * the known plan id, and the label rendered in plan pickers. Do not branch
 * on the app flavor.
 */
export const isChinaPlan = (...names: unknown[]): boolean =>
  names.some((name: unknown): boolean =>
    CHINA_PLAN_LABELS.has(normalizeLabel(name)),
  );

interface ChinaPlanPolicyName {
  id?: string;
  plan?: {
    id?: string;
    name?: unknown;
  } | null;
}

interface ChinaPlanSponsorshipName {
  fauxPlanName?: unknown;
  policyId?: string;
}

export const isChinaPlanPolicy = (
  policy: ChinaPlanPolicyName | null | undefined,
  sponsorships?: readonly ChinaPlanSponsorshipName[] | null,
): boolean => {
  if (policy?.plan?.id === CHINA_PLAN_ID) {
    return true;
  }

  const policyId = policy?.id;
  const sponsorship = sponsorships?.find(
    (item: ChinaPlanSponsorshipName): boolean =>
      typeof policyId === 'string' &&
      policyId.length > 0 &&
      item.policyId === policyId,
  );

  return isChinaPlan(policy?.plan?.name, sponsorship?.fauxPlanName);
};

