import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Modal, TouchableOpacity, View } from 'react-native';
import LinearGradient from 'react-native-linear-gradient';

import type { Policys, Sponsorship } from '@api/api-types';
import AppText from '@components/app-text/app-text';
import constants from '@constants';
import { isChinaPlanPolicy } from '@helper/china-plan';

import styles from './china-plan-prescription-alert.styles';

export const CHINA_PLAN_ALERT_DELAY_MS = 300;

const BUTTON_COLORS = ['#11b2d2', '#23a753'];

interface ChinaPlanPrescriptionAlertProps {
  onClose: () => void;
  visible: boolean;
}

const ChinaPlanPrescriptionAlert = ({
  onClose,
  visible,
}: ChinaPlanPrescriptionAlertProps): React.ReactElement => {
  const title = constants.i18n.t('prescription_gentle_reminder');
  const firstMessage = constants.i18n.t('prescription_reminder_1');
  const secondMessage = constants.i18n.t('prescription_reminder_2');
  const confirmLabel = constants.i18n.t('prescription_button');

  return (
    <Modal
      animationType="slide"
      onRequestClose={onClose}
      testID="china-plan-prescription-alert"
      transparent
      visible={visible}
    >
      <View style={styles.overlay} testID="china-plan-prescription-alert-backdrop">
        <View style={styles.card}>
          <AppText style={styles.title}>{title}</AppText>
          <AppText style={styles.message}>{firstMessage}</AppText>
          <AppText style={styles.message}>{secondMessage}</AppText>
          <LinearGradient
            colors={BUTTON_COLORS}
            end={{ x: 1, y: 0 }}
            start={{ x: 0, y: 0 }}
            style={styles.button}
          >
            <TouchableOpacity
              accessibilityLabel={confirmLabel}
              accessibilityRole="button"
              onPress={onClose}
              style={styles.buttonHit}
              testID="china-plan-prescription-alert-confirm"
            >
              <AppText style={styles.buttonText}>{confirmLabel}</AppText>
            </TouchableOpacity>
          </LinearGradient>
        </View>
      </View>
    </Modal>
  );
};

interface UseChinaPlanPrescriptionAlertResult {
  alert: React.ReactElement;
  notifyPlanSelected: (policy: Policys, delayMs?: number) => void;
}

export const useChinaPlanPrescriptionAlert = (
  sponsorships?: readonly Sponsorship[] | null,
): UseChinaPlanPrescriptionAlertResult => {
  const [visible, setVisible] = useState<boolean>(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    (): (() => void) => (): void => {
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    },
    [],
  );

  const notifyPlanSelected = useCallback(
    (policy: Policys, delayMs: number = CHINA_PLAN_ALERT_DELAY_MS): void => {
      if (!isChinaPlanPolicy(policy, sponsorships)) {
        return;
      }

      if (timerRef.current) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }

      if (delayMs <= 0) {
        setVisible(true);
        return;
      }

      // The plan sheet is a modal. Presenting this alert in the same frame
      // drops it on iOS, so wait until that sheet has closed.
      timerRef.current = setTimeout((): void => {
        timerRef.current = null;
        setVisible(true);
      }, delayMs);
    },
    [sponsorships],
  );

  const handleClose = useCallback((): void => {
    setVisible(false);
  }, []);

  return {
    alert: (
      <ChinaPlanPrescriptionAlert onClose={handleClose} visible={visible} />
    ),
    notifyPlanSelected,
  };
};

export default ChinaPlanPrescriptionAlert;

