describe('China Plan prescription reminder', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    act(() => {
      jest.runOnlyPendingTimers();
    });
    jest.useRealTimers();
  });

  test('matches catalog names, rendered labels, and the shared plan id', () => {
    expect(isChinaPlanPolicy(chinaPolicy)).toBe(true);
