    expect(screen.getByText('Gentle Reminder')).toBeTruthy();
    expect(
      screen.getByText(
        'Prescription must be uploaded in order to access this service.',
      ),
    ).toBeTruthy();
    expect(
      screen.getByText(
        'Please kindly prepare your local prescription before making appointment.',
      ),
    ).toBeTruthy();
    expect(screen.getByText('Yes, I have local prescription.')).toBeTruthy();
  });

  test('shows immediately when the consult chip selects China Plan', () => {
    const screen = render(<AlertHost delayMs={0} policy={healsChinaPolicy} />);

    fireEvent.press(screen.getByTestId('select-plan'));

    expect(alertVisible(screen)).toBe(true);
  });

  test('does not show for another plan', () => {
    const screen = render(<AlertHost delayMs={0} policy={otherPolicy} />);

    fireEvent.press(screen.getByTestId('select-plan'));

    expect(screen.queryByTestId('china-plan-prescription-alert')).toBeNull();
  });

  test('closes from the confirmation button', () => {
    const screen = render(<AlertHost delayMs={0} policy={chinaPolicy} />);

    fireEvent.press(screen.getByTestId('select-plan'));
    fireEvent.press(screen.getByTestId('china-plan-prescription-alert-confirm'));

    expect(screen.queryByTestId('china-plan-prescription-alert')).toBeNull();
  });
});

