      timerRef.current = setTimeout((): void => {
        timerRef.current = null;
        setVisible(true);
      }, delayMs);
    },
    [sponsorships],
  );

  const handleClose = useCallback((): void => {
    setVisible(false);
  }, []);

  const handleViewCategory = useCallback((): void => {
    const planId = policyRef.current?.plan?.id?.trim() ?? '';

    setVisible(false);

    if (!planId) {
      return;
