    constants.$NavigationActions.navigate(
      constants.$routeNames.medicationListScreen,
      { planId },
    );
  }, []);

  return {
    alert: (
      <ChinaPlanPrescriptionAlert
        onClose={handleClose}
        onViewCategory={handleViewCategory}
        visible={visible}
      />
    ),
    notifyPlanSelected,
  };
};

