const ts = require('typescript');
const path = require('path');
const { execFileSync } = require('child_process');
const root = process.cwd();
const rel = 'src/screens/home/home-screen/home-screen.tsx';
const abs = path.join(root, rel);
const base = '119cc9cd051ada9feabaa75e59c19735258b0d80';
const head = 'b83d3f2261792cac9a8a732d36fb983e49ecea31';
const cfgPath = path.join(root, 'tsconfig.json');
const cfg = ts.readConfigFile(cfgPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(cfg.config, ts.sys, root);
const options = { ...parsed.options, noEmit: true };
console.log('typescript', ts.version, 'rootFiles', parsed.fileNames.length, 'configErrors', parsed.errors.length);
const run = (label, sha) => {
  const content = execFileSync('git', ['show', `${sha}:${rel}`], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  const host = ts.createCompilerHost(options, true);
  const origRead = host.readFile.bind(host);
  host.readFile = (f) => (path.resolve(f) === abs ? content : origRead(f));
  const origGet = host.getSourceFile.bind(host);
  host.getSourceFile = (f, lang, onErr, shouldCreate) =>
    path.resolve(f) === abs ? ts.createSourceFile(f, content, lang, true) : origGet(f, lang, onErr, shouldCreate);
  const program = ts.createProgram({ rootNames: parsed.fileNames, options, host });
  const sf = program.getSourceFile(abs);
  if (!sf) { console.log(label, 'SOURCE FILE NOT IN PROGRAM'); return null; }
  const fmt = (d) => {
    const pos = d.start !== undefined ? sf.getLineAndCharacterOfPosition(d.start) : { line: -1, character: 0 };
    const text = d.start !== undefined ? sf.text.slice(d.start, d.start + (d.length || 0)).split('\n')[0].slice(0, 60) : '';
    return { code: d.code, line: pos.line + 1, text, msg: ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0, 160) };
  };
  const syntactic = program.getSyntacticDiagnostics(sf).map(fmt);
  const semantic = program.getSemanticDiagnostics(sf).map(fmt);
  const suggestion = program.getSuggestionDiagnostics(sf).map(fmt);
  console.log(label, 'syntactic', syntactic.length, 'semantic', semantic.length, 'suggestion', suggestion.length);
  return { syntactic, semantic, suggestion };
};
const b = run('BASE', base);
const h = run('HEAD', head);
const key = (d) => `${d.code}|${d.text}|${d.msg}`;
for (const kind of ['syntactic', 'semantic', 'suggestion']) {
  const count = (arr) => arr.reduce((m, d) => m.set(key(d), (m.get(key(d)) || 0) + 1), new Map());
  const bc = count(b[kind]); const hc = count(h[kind]);
  const added = []; const removed = [];
  for (const [k, n] of hc) { const diff = n - (bc.get(k) || 0); if (diff > 0) added.push(`${k} x${diff}`); }
  for (const [k, n] of bc) { const diff = n - (hc.get(k) || 0); if (diff > 0) removed.push(`${k} x${diff}`); }
  console.log(`--- ${kind}: added ${added.length}, removed ${removed.length}`);
  added.forEach((a) => console.log('  + ' + a));
  removed.forEach((a) => console.log('  - ' + a));
}
const inRange = (d) => d.line >= 936 && d.line <= 962;
console.log('--- HEAD diagnostics inside changed hunk lines 936-962');
for (const kind of ['syntactic', 'semantic', 'suggestion']) {
  h[kind].filter(inRange).forEach((d) => console.log(`  ${kind} TS${d.code} L${d.line} ${d.text} :: ${d.msg}`));
}
const dep = h.suggestion.filter((d) => d.code === 6385 || d.code === 6387);
console.log('--- HEAD deprecated suggestions total', dep.length);
dep.forEach((d) => console.log(`  TS${d.code} L${d.line} ${d.text}`));
